<?php declare(strict_types=1); namespace Annam; $title=$spec['title']; $subtitle=count($records).' records'; ?>
<header class="php-section-head"><div><?php if ($key === 'dishes'): ?><div class="php-tabs"><a class="<?= $kind==='scheduled'?'selected':'' ?>" href="?kind=scheduled">Meals</a><a class="<?= $kind==='courier'?'selected':'' ?>" href="?kind=courier">Other items</a><a href="/manage/dishes/menu/">Breakfast · Lunch · Dinner →</a></div><?php endif; ?></div><a class="o-btn o-btn-primary" href="/manage/<?= e($key) ?>/new/?kind=<?= e($kind) ?>">+ Add <?= $key==='dishes'?'dish':'record' ?></a></header>
<form class="php-search" method="get"><input type="hidden" name="kind" value="<?= e($kind) ?>"><input name="q" value="<?= e($query) ?>" placeholder="Search <?= e(strtolower($spec['title'])) ?>" aria-label="Search"><button class="o-btn" type="submit">Search</button></form>
<div class="o-card php-table-wrap"><table class="php-table"><thead><tr><th>Name</th><?php if ($key==='zones'): ?><th>Pincode</th><th>Fee</th><th>Minimum</th><?php elseif ($key==='dishes'): ?><th>Price</th><th>Type</th><?php endif; ?><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach ($records as $row): $active = $row[$key==='pages'?'published':'active']; ?><tr><td><div class="php-record-name"><?php if (!empty($row['image'])): ?><img src="<?= e(image_url($row['image'])) ?>" alt="" width="52" height="52" loading="lazy"><?php endif; ?><b><?= e($row['name']??$row['title']??$row['area_name']??$row['label']??'') ?></b></div></td>
<?php if ($key==='zones'): ?><td><?= e($row['pincode']) ?></td><td><?= money($row['delivery_fee']) ?></td><td><?= money($row['min_order']) ?></td><?php elseif ($key==='dishes'): ?><td><?= money($row['price']) ?></td><td><?= $row['fulfilment']==='scheduled'?'Meal':'Shop item' ?></td><?php endif; ?>
<td><form method="post" action="/manage/<?= e($key) ?>/<?= e($row['id']) ?>/toggle/"><?= csrf() ?><button class="php-toggle <?= $active?'is-on':'' ?>" type="submit" role="switch" aria-checked="<?= $active?'true':'false' ?>" aria-label="<?= e(($active?'Hide ':'Show ').($row['name']??$row['area_name']??$row['title']??$row['label']??'')) ?>"><i></i></button></form></td><td><a class="o-btn" href="/manage/<?= e($key) ?>/<?= e($row['id']) ?>/">Edit</a></td></tr><?php endforeach; ?>
<?php if (!$records): ?><tr><td colspan="6">No matching records.</td></tr><?php endif; ?></tbody></table></div>
